('连续最大子段和', '给定整数数组，请输出连续子数组的最大和。', '["数组","动态规划"]', '[{"input":"5\\n-2 1 -3 4 -1","output":"4"},{"input":"3\\n-1 -2 -3","output":"-1"}]', '[{"language":"java8","timeLimit":1000,"memoryLimit":128},{"language":"java21","timeLimit":1000,"memoryLimit":128},{"language":"gcc7","timeLimit":1000,"memoryLimit":128},{"language":"gcc8","timeLimit":1000,"memoryLimit":128},{"language":"gcc9","timeLimit":1000,"memoryLimit":128},{"language":"g++7","timeLimit":1000,"memoryLimit":128},{"language":"g++8","timeLimit":1000,"memoryLimit":128},{"language":"g++9","timeLimit":1000,"memoryLimit":128},{"language":"python3","timeLimit":1000,"memoryLimit":128},{"language":"pypy3","timeLimit":1000,"memoryLimit":128},{"language":"javascript","timeLimit":1000,"memoryLimit":128},{"language":"typescript","timeLimit":1000,"memoryLimit":128}]', 0, 0, 1, 1),
