('数字 7 的个数', '给定一个非负整数 n，请统计从 1 到 n 的所有数字中，数字字符 7 出现的次数。', '["数学","统计"]', '[{"input":"20","output":"2"},{"input":"7","output":"1"}]', '[{"language":"java8","timeLimit":1000,"memoryLimit":128},{"language":"java21","timeLimit":1000,"memoryLimit":128},{"language":"gcc7","timeLimit":1000,"memoryLimit":128},{"language":"gcc8","timeLimit":1000,"memoryLimit":128},{"language":"gcc9","timeLimit":1000,"memoryLimit":128},{"language":"g++7","timeLimit":1000,"memoryLimit":128},{"language":"g++8","timeLimit":1000,"memoryLimit":128},{"language":"g++9","timeLimit":1000,"memoryLimit":128},{"language":"python3","timeLimit":1000,"memoryLimit":128},{"language":"pypy3","timeLimit":1000,"memoryLimit":128},{"language":"javascript","timeLimit":1000,"memoryLimit":128},{"language":"typescript","timeLimit":1000,"memoryLimit":128}]', 0, 0, 1, 1);
